package com.yeyamo_mobile.api.culture_service.application;
import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo.events.EventEnvelope;import com.yeyamo_mobile.api.culture_service.infrastructure.outbox.*;import java.util.UUID;import org.slf4j.MDC;import org.springframework.stereotype.Component;
@Component public class CultureEventPublisher{private final CultureOutboxRepository repository;private final ObjectMapper mapper;public CultureEventPublisher(CultureOutboxRepository r,ObjectMapper m){repository=r;mapper=m;}public void publish(String type,UUID aggregate,Object payload){try{EventEnvelope<Object> envelope=EventEnvelope.create(type,"culture-service",MDC.get("correlationId"),aggregate.toString(),payload);repository.save(CultureOutbox.create(envelope.eventId(),aggregate.toString(),type,mapper.writeValueAsString(envelope),envelope.occurredAt()));}catch(Exception e){throw new IllegalStateException("Culture event serialization failed",e);}}}
